#!/usr/bin/env python3
"""Focused regression test for the MPTCP sysctl signedness fix.

It reads the actual _prop_get_connection_mptcp_flags() implementation from the
supplied nm-device.c, extracts the declared type of `v`, compiles a tiny C
harness that reproduces the exact control flow around
nm_platform_sysctl_get_int32(..., -1) with that same type, and asserts the
security invariant.

Usage:
    mptcp_signedness_test.py <path-to-nm-device.c> <baseline|candidate>

  baseline  : the unpatched implementation MUST reproduce the bug
              (read error -> mptcp NOT disabled)
  candidate : the patched implementation MUST fix it
              (read error -> mptcp disabled), while normal readable values
              keep their behavior.

This is a focused reproduction of the upstream regression intent; it does not
build the whole NetworkManager project.
"""
from __future__ import annotations

import re
import subprocess
import sys
import tempfile
from pathlib import Path

FUNC = "_prop_get_connection_mptcp_flags"


def extract_v_type(source: Path) -> str:
    text = source.read_text(encoding="utf-8", errors="replace")
    start = text.find(FUNC)
    if start < 0:
        raise SystemExit(f"FAIL: {FUNC} not found in {source}")
    # The guard block begins after the ALSO_WITHOUT_SYSCTL test.
    match = re.search(
        r"NM_MPTCP_FLAGS_ALSO_WITHOUT_SYSCTL\)\)\s*\{\s*\n\s*(\w+)\s+v\s*;",
        text[start:],
    )
    if not match:
        raise SystemExit("FAIL: could not locate the sysctl guard declaration of v")
    return match.group(1)


def build_and_run(source: Path, vtype: str, workdir: Path) -> dict[str, int]:
    c_file = workdir / "mptcp_repro.c"
    exe = workdir / "mptcp_repro"
    c_file.write_text(
        f"""
#include <stdio.h>
#include <stdint.h>

typedef unsigned int  guint32;
typedef signed int    gint32;

/* Faithful stand-in for nm_platform_sysctl_get_int32(): returns the caller's
 * fallback when /proc/sys/net/mptcp/enabled cannot be read (e.g. no MPTCP
 * support in the kernel). */
static gint32
nm_platform_sysctl_get_int32(gint32 fallback)
{{
    return fallback;
}}

typedef {vtype} v_type_t;

static int
mptcp_disabled_for_sysctl_return(gint32 sysctl_value)
{{
    v_type_t v;

    v = nm_platform_sysctl_get_int32(sysctl_value);
    if (v <= 0)
        return 1; /* NM_MPTCP_FLAGS_DISABLED */
    return 0;
}}

int
main(void)
{{
    /* readable sysctl: MPTCP enabled */
    printf("readable_1=%d\\n", mptcp_disabled_for_sysctl_return(1));
    /* readable sysctl: MPTCP disabled */
    printf("readable_0=%d\\n", mptcp_disabled_for_sysctl_return(0));
    /* unreadable sysctl: error fallback -1 (kernel without MPTCP) */
    printf("unreadable_err=%d\\n", mptcp_disabled_for_sysctl_return(-1));
    return 0;
}}
""",
        encoding="utf-8",
    )
    compile_proc = subprocess.run(
        ["gcc", "-O0", "-Wall", "-Wextra", "-Werror", str(c_file), "-o", str(exe)],
        capture_output=True,
        text=True,
    )
    if compile_proc.returncode != 0:
        raise SystemExit(
            "FAIL: gcc compilation failed\n"
            + compile_proc.stdout
            + compile_proc.stderr
        )
    run_proc = subprocess.run([str(exe)], capture_output=True, text=True)
    results: dict[str, int] = {}
    for line in run_proc.stdout.splitlines():
        key, _, value = line.partition("=")
        if _ == "=":
            results[key] = int(value)
    return results


def main() -> int:
    if len(sys.argv) != 3:
        raise SystemExit(__doc__)
    source = Path(sys.argv[1])
    mode = sys.argv[2]
    if mode not in ("baseline", "candidate"):
        raise SystemExit("mode must be 'baseline' or 'candidate'")

    vtype = extract_v_type(source)
    print(f"source={source}")
    print(f"declared_type_of_v={vtype}")
    print(f"signed={'yes' if vtype == 'gint32' else 'no'}")

    with tempfile.TemporaryDirectory(prefix="mptcp-test-", dir="/tmp/opencode") as tmp:
        results = build_and_run(source, vtype, Path(tmp))

    print(f"results={results}")
    failures: list[str] = []

    # Behavior that must hold in both versions for readable values.
    if results.get("readable_1") != 0:
        failures.append("readable sysctl=1 should leave MPTCP enabled")
    if results.get("readable_0") != 1:
        failures.append("readable sysctl=0 should disable MPTCP")

    err = results.get("unreadable_err")
    if mode == "candidate":
        if vtype != "gint32":
            failures.append("candidate must declare gint32 v")
        if err != 1:
            failures.append(
                "FIX NOT EFFECTIVE: unreadable sysctl (-1) must disable MPTCP"
            )
        else:
            print("INVARIANT_OK: unreadable sysctl -> NM_MPTCP_FLAGS_DISABLED")
    else:  # baseline
        if vtype not in ("guint32", "guint", "unsigned int"):
            failures.append(f"unexpected baseline type {vtype}")
        if err != 0:
            failures.append(
                "BASELINE DID NOT REPRODUCE BUG: expected unreadable sysctl to leave MPTCP enabled"
            )
        else:
            print("BUG_REPRODUCED: unreadable sysctl (-1) leaves MPTCP enabled")

    if failures:
        for failure in failures:
            print("FAIL:", failure)
        return 1
    print(f"MODE={mode} PASS")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

