#!/usr/bin/env python3
"""Compile the ACTUAL _prop_get_connection_mptcp_flags() body from the supplied
nm-device.c against minimal faithful stubs, and exercise the security path.

Unlike a hand-written replica, this test extracts the real function text from
the target source and compiles it, so the changed declaration under test is the
candidate's own code.

Usage:
    mptcp_function_compile_test.py <path-to-nm-device.c> <baseline|candidate>
"""
from __future__ import annotations

import subprocess
import sys
import tempfile
from pathlib import Path

FUNC_NAME = "_prop_get_connection_mptcp_flags"


def extract_function(source: Path) -> str:
    text = source.read_text(encoding="utf-8", errors="replace")
    marker = f"static NMMptcpFlags\n{FUNC_NAME}(NMDevice *self)"
    start = text.find(marker)
    if start < 0:
        raise SystemExit("FAIL: could not locate the function signature")
    brace = text.find("{", start)
    if brace < 0:
        raise SystemExit("FAIL: could not locate function body")
    depth = 0
    for index in range(brace, len(text)):
        char = text[index]
        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return text[start : index + 1]
    raise SystemExit("FAIL: unbalanced braces in extracted function")


STUBS = r"""
#include <stdio.h>
#include <stdint.h>

typedef unsigned int       guint32;
typedef signed int         gint32;
typedef unsigned long long guint64;
typedef int                gboolean;
#define TRUE  1
#define FALSE 0
#define G_MAXINT64 0x7fffffffffffffffULL

typedef struct NMDevice          NMDevice;
typedef struct NMConnection      NMConnection;
typedef struct NMSettingConnection NMSettingConnection;

typedef enum {
    NM_MPTCP_FLAGS_NONE                       = 0,
    NM_MPTCP_FLAGS_DISABLED                   = 0x1,
    NM_MPTCP_FLAGS_ENABLED                    = 0x2,
    NM_MPTCP_FLAGS_ALSO_WITHOUT_SYSCTL        = 0x4,
    NM_MPTCP_FLAGS_ALSO_WITHOUT_DEFAULT_ROUTE = 0x8,
    NM_MPTCP_FLAGS_SIGNAL                     = 0x10,
    NM_MPTCP_FLAGS_SUBFLOW                    = 0x20,
    NM_MPTCP_FLAGS_BACKUP                     = 0x40,
    NM_MPTCP_FLAGS_FULLMESH                   = 0x80,
} NMMptcpFlags;

#define _NM_MPTCP_FLAGS_DEFAULT ((NMMptcpFlags) (NM_MPTCP_FLAGS_ENABLED | NM_MPTCP_FLAGS_SUBFLOW))
#define NM_FLAGS_HAS(flags, f)   (((flags) & (f)) == (f))
#define NM_FLAGS_UNSET(flags, f) ((flags) & ~(f))

#define NM_IS_DEVICE(x) ((x) != 0)
#define g_return_val_if_fail(expr, val) \
    do { if (!(expr)) return (val); } while (0)

#define NM_CONFIG_GET_DATA 0
#define NM_CON_DEFAULT(name) (name)
#define NMP_SYSCTL_PATHID_ABSOLUTE(path) (path)

/* controllable stubs */
static gint32         g_sysctl_ret     = -1;
static guint64        g_conn_default   = NM_MPTCP_FLAGS_NONE;
static NMMptcpFlags   g_setting_flags  = NM_MPTCP_FLAGS_NONE;
static NMConnection  *g_connection     = 0;
static NMDevice      *g_platform       = (NMDevice *) 1;

static NMDevice *nm_device_get_platform(NMDevice *self) { (void) self; return g_platform; }
static gint32 nm_platform_sysctl_get_int32(NMDevice *platform, const char *path, gint32 fallback)
{ (void) platform; (void) path; (void) fallback; return g_sysctl_ret; }
static NMConnection *nm_device_get_applied_connection(NMDevice *self) { (void) self; return g_connection; }
static NMSettingConnection *nm_connection_get_setting_connection(NMConnection *c)
{ return (NMSettingConnection *) c; }
static NMMptcpFlags nm_setting_connection_get_mptcp_flags(NMSettingConnection *s)
{ (void) s; return g_setting_flags; }
static guint64 nm_config_data_get_connection_default_int64(int data, const char *name, NMDevice *self,
                                                           guint64 min, guint64 max, guint64 def)
{ (void) data; (void) name; (void) self; (void) min; (void) max; (void) def; return g_conn_default; }
static NMMptcpFlags nm_mptcp_flags_normalize(NMMptcpFlags flags) { return flags; }

/* ---- actual function body extracted from the supplied target source ---- */
"""

MAIN = r"""
int main(void)
{
    NMDevice *dev = (NMDevice *) 1;
    NMMptcpFlags f;

    /* unreadable sysctl (kernel without MPTCP): fallback -1 */
    g_sysctl_ret = -1;
    f = _prop_get_connection_mptcp_flags(dev);
    printf("unreadable_err_disabled=%d\n", NM_FLAGS_HAS(f, NM_MPTCP_FLAGS_DISABLED) ? 1 : 0);

    /* readable sysctl: MPTCP enabled */
    g_sysctl_ret = 1;
    f = _prop_get_connection_mptcp_flags(dev);
    printf("readable_1_disabled=%d\n", NM_FLAGS_HAS(f, NM_MPTCP_FLAGS_DISABLED) ? 1 : 0);

    /* readable sysctl: MPTCP disabled */
    g_sysctl_ret = 0;
    f = _prop_get_connection_mptcp_flags(dev);
    printf("readable_0_disabled=%d\n", NM_FLAGS_HAS(f, NM_MPTCP_FLAGS_DISABLED) ? 1 : 0);

    return 0;
}
"""


def main() -> int:
    if len(sys.argv) != 3:
        raise SystemExit(__doc__)
    source = Path(sys.argv[1])
    mode = sys.argv[2]
    if mode not in ("baseline", "candidate"):
        raise SystemExit("mode must be baseline or candidate")

    function_text = extract_function(source)
    declared = "gint32 v;" if "gint32 v;" in function_text else ("guint32 v;" if "guint32 v;" in function_text else "?")
    print(f"extracted_declaration={declared}")

    with tempfile.TemporaryDirectory(prefix="mptcp-func-", dir="/tmp/opencode") as tmp:
        c_file = Path(tmp) / "func_test.c"
        exe = Path(tmp) / "func_test"
        c_file.write_text(STUBS + function_text + "\n" + MAIN, encoding="utf-8")
        compile_proc = subprocess.run(
            ["gcc", "-O0", "-Wall", "-Wextra", "-Werror", str(c_file), "-o", str(exe)],
            capture_output=True, text=True,
        )
        if compile_proc.returncode != 0:
            print(compile_proc.stdout)
            print(compile_proc.stderr)
            print("FAIL: gcc failed to compile the extracted function")
            return 1
        run_proc = subprocess.run([str(exe)], capture_output=True, text=True)
        print(run_proc.stdout.strip())

    results = {}
    for line in run_proc.stdout.splitlines():
        k, _, v = line.partition("=")
        if _ == "=":
            results[k] = int(v)

    failures = []
    if results.get("readable_1_disabled") != 0:
        failures.append("readable=1 must leave MPTCP enabled")
    if results.get("readable_0_disabled") != 1:
        failures.append("readable=0 must disable MPTCP")
    err = results.get("unreadable_err_disabled")
    if mode == "candidate":
        if declared != "gint32 v;":
            failures.append("candidate must declare gint32 v")
        if err != 1:
            failures.append("FIX NOT EFFECTIVE: unreadable sysctl must disable MPTCP")
        else:
            print("COMPILED_INVARIANT_OK")
    else:
        if err != 0:
            failures.append("baseline did not reproduce the bug")
        else:
            print("COMPILED_BUG_REPRODUCED")

    if failures:
        for f in failures:
            print("FAIL:", f)
        return 1
    print(f"COMPILE_MODE={mode} PASS")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

